{
  "name": "Process Form Submissions",
  "description": "Summarise form submissions, classify urgency, post urgent ones to Discord, and log all to Google Sheets.",
  "nodes": [
    {
      "id": "webhook",
      "type": "core.webhook_trigger",
      "label": "Form Webhook",
      "config": {
        "requiredFields": []
      }
    },
    {
      "id": "summarise",
      "type": "ai.llm",
      "label": "Summarise Submission",
      "config": {
        "prompt": "Summarise this form submission in one concise sentence: {{trigger.message}}",
        "system": "",
        "temperature": 0.3,
        "json": false
      }
    },
    {
      "id": "classify",
      "type": "ai.agent",
      "label": "Classify Urgency",
      "config": {
        "objective": "Determine if the form submission is urgent based on the content. Choose 'urgent' if it requires immediate attention, otherwise choose 'normal'.",
        "choices": [
          "urgent",
          "normal"
        ],
        "tools": [],
        "system": "",
        "temperature": 0
      }
    },
    {
      "id": "check_urgent",
      "type": "core.branch",
      "label": "Is Urgent?",
      "config": {
        "left": "{{input.decision}}",
        "operator": "equals",
        "right": "urgent"
      }
    },
    {
      "id": "discord",
      "type": "integration.discord",
      "label": "Post to Discord",
      "config": {
        "content": "🚨 Urgent submission: {{steps.summarise.output.text}}"
      }
    },
    {
      "id": "sheets",
      "type": "integration.sheets",
      "label": "Log to Google Sheet",
      "config": {
        "spreadsheetId": "",
        "sheet": "Sheet1",
        "values": [
          "{{trigger.name}}",
          "{{steps.summarise.output.text}}",
          "{{steps.classify.output.decision}}"
        ],
        "valueInputOption": "USER_ENTERED"
      }
    }
  ],
  "edges": [
    {
      "source": "webhook",
      "target": "summarise",
      "sourceHandle": null
    },
    {
      "source": "summarise",
      "target": "classify",
      "sourceHandle": null
    },
    {
      "source": "classify",
      "target": "check_urgent",
      "sourceHandle": null
    },
    {
      "source": "check_urgent",
      "target": "discord",
      "sourceHandle": "true"
    },
    {
      "source": "check_urgent",
      "target": "sheets",
      "sourceHandle": "true"
    },
    {
      "source": "check_urgent",
      "target": "sheets",
      "sourceHandle": "false"
    }
  ],
  "unsupported": []
}

